#include <bits/stdc++.h>
using namespace std;

int main(void){
	int t;
	cin>>t;

	for(int itest=0;itest<t;itest++){
		int n,d;
		cin>>n>>d;

		vector<int>a(n),b(n);
		for(int i=0;i<n;i++)cin>>a[i];
		for(int i=0;i<n;i++)cin>>b[i];

		int x;
		queue<int>q;
		for(int i=0;i<n;i++){
			for(int j=0;j<a[i];j++)q.push(i);
			for(int j=0;j<b[i];j++)q.pop();
			while((!q.empty())&&(q.front()==i-d))q.pop();
		}
		cout<<((int)(q.size()))<<endl;
	}
	return 0;
}
